static int port_hdr_init(struct platform_device *pdev,
			 struct dfl_feature *feature)
{
	struct dfl_feature_dev_data *fdata;
	void __iomem *base;
	u8 rev;

	fdata = to_dfl_feature_dev_data(&pdev->dev);

	base = dfl_get_feature_ioaddr_by_id(fdata, PORT_FEATURE_ID_HEADER);

	rev = dfl_feature_revision(base);

	if (rev < 2)
		port_reset(pdev);
	else if (rev > 2)
		dev_info(&pdev->dev, "unexpected port feature revision, %u\n", rev);

#if LINUX_VERSION_CODE < KERNEL_VERSION(5, 4, 0) && RHEL_RELEASE_CODE < 0x803
	return device_add_groups(&pdev->dev, port_hdr_groups);
#else
	return 0;
#endif
}

#if LINUX_VERSION_CODE < KERNEL_VERSION(5, 4, 0) && RHEL_RELEASE_CODE < 0x803
static void port_hdr_uinit(struct platform_device *pdev,
			   struct dfl_feature *feature)
{
	device_remove_groups(&pdev->dev, port_hdr_groups);
}
#endif

static long
port_hdr_ioctl(struct platform_device *pdev, struct dfl_feature *feature,
	       unsigned int cmd, unsigned long arg)
{
	long ret;

	switch (cmd) {
	case DFL_FPGA_PORT_RESET:
		if (!arg)
			ret = port_reset(pdev);
		else
			ret = -EINVAL;
		break;
	default:
		dev_dbg(&pdev->dev, "%x cmd not handled", cmd);
		ret = -ENODEV;
	}

	return ret;
}

